/* Signature Scottish Gaelic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Hamishbhan": "From Hamish + ban (white).", "Mhairigorm": "From Mhairi + gorm (blue).", "Alasdairruadh": "From Alasdair + ruadh (red).", "Catrionadonn": "From Catriona + donn (brown).", "Ewanmor": "From Ewan + mor (great).", "Ishbelbheag": "From Ishbel + bheag (little).", "MacHamishbhan": "Signature surname in Mac style.", "NicMhairigorm": "Signature feminine surname in Nic style.", "MacAlasdairruadh": "Signature surname in Mac style.", "MacEwanmor": "Signature surname in Mac style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Hamishbhan';
console.log(lookup(q));

